@Composable
fun Wordmark(height: Dp, textColor: Color, accent: Color, modifier: Modifier = Modifier) {
    val luc = remember { PathParser().parsePathString(LUC).toPath() }
    val bao = remember { PathParser().parsePathString(BAO).toPath() }
    Canvas(modifier.height(height).width(height * (W / H))) {
        val s = size.height / H
        scale(s, s, pivot = Offset.Zero) {
            translate(-MIN_X, -MIN_Y) {
                drawPath(luc, textColor)
                drawPath(bao, accent)
            }
        }
    }
}

/** Leaf logo followed by the "Lục Bảo" wordmark. */
@Composable
fun BrandMark(height: Dp, modifier: Modifier = Modifier) {
    val c = Luc.colors
    Row(modifier, verticalAlignment = Alignment.CenterVertically) {
        LeafLogo(height * 1.15f)
        Spacer(Modifier.width(height * 0.35f))
        Wordmark(height, c.text, c.primary)
    }
}
